"use strict";
const assert=require("node:assert/strict"),r=require("./fixtures/d3d_cursor_reference.json");
(async()=>{const{cursor_pixel,cursor_display}=await import('../lib/d3d_cursor_wire.mjs');assert.equal(r.extent,64);assert.equal(r.cursorSize,32);assert.equal(r.frames.length,8);assert.deepEqual(r.frames.map(f=>f.visible),[0,1,1,0,1,1,1,0]);assert.deepEqual(r.gpuCube,{edge:64,levels:2,face:4,level:1});assert.equal(cursor_pixel(0,0,0),0xffff0000);assert.equal(cursor_pixel(0,31,0),0x8000ff00);assert.equal(cursor_pixel(0,0,31),0x000000ff);assert.equal(cursor_pixel(0,31,31),0xffffffff);assert.equal(cursor_pixel(1,0,0),0xffff00ff);const picture=cursor_display(r.frames[1]);assert.equal(picture.readUInt32LE((19*64+21)*4),0xffff0000);assert.equal(picture.readUInt32LE((35*64+21)*4),r.backgroundARGB);assert.equal(picture.readUInt32LE((19*64+37)*4),0xff10a030);assert.equal(picture.readUInt32LE((35*64+37)*4),0xffffffff);for(const frame of r.frames){const data=cursor_display(frame);assert.equal(data.length,16384);for(let p=3;p<data.length;p+=4)assert.equal(data[p],255);}assert.match(r.scope,/non32 software cursor/);assert.equal(r.sources.length,4);for(const s of r.sources){assert.match(s.sha256,/^[a-f0-9]{64}$/);assert.match(s.blobSha1,/^[a-f0-9]{40}$/);}console.log('PASS independent hardware cursor reference: alpha quadrants, retained input images, previous BOOL, OS movement, signed client positions, hotspots/clipping and source cube face/mip; explicit non32/native scope');})().catch(e=>{console.error(e);process.exitCode=1;});
